public class FMCleaning implements WorkflowElementCompletedEventHandler, WorkflowElementStartedEventHandler
{
}

Method.Source:
public void completed(WorkflowElementEventArgs _workflowElementEventArgs)
{

    FMvehicleMaintenance        vehicleMaintenance;
    FMvehicle                   vehicle;

    ttsbegin;

    select firstonly forupdate vehicleMaintenance where vehicleMaintenance.RecId == _workflowElementEventArgs.parmWorkflowContext().parmRecId();

    vehicleMaintenance.DateCompleted = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    vehicleMaintenance.Status = FMStatus::Done;


    select firstonly forupdate vehicle where vehicle.RecId == vehicleMaintenance.VehicleRelation;

    vehicle.Status = FMVehicleStatus::Available;
    vehicle.update();

    vehicleMaintenance.Mileage = int642int(vehicle.Mileage);
    vehicleMaintenance.update();



    ttscommit;






}

/// <summary>
///    Empty event handler
/// </summary>
/// <param name="_workflowElementEventArgs">
///    A <c>WorkflowElementEventArgs</c> instance.
/// </param>
/// <remarks>
///    This method is called from workflow framework when the approval is started.
/// </remarks>
public void started(WorkflowElementEventArgs _workflowElementEventArgs)
{

    FMVehicleMaintenance vehicleMaintenance;

    ttsbegin;

    select firstonly forupdate vehicleMaintenance where vehicleMaintenance.RecId == _workflowElementEventArgs.parmWorkflowContext().parmRecId();


    vehicleMaintenance.Status = FMStatus::AwaitingCleaning;
    vehicleMaintenance.update();

    ttscommit;

}
